-- Uldum spawns, part 4 of 8: the rows of this part are deleted by key range before they are inserted, so the file can run twice.
-- Based on Legends of Azeroth 5.4.8 and The Cataclysm Preservation Project 4.3.4.

DELETE FROM `creature_addon` WHERE `guid` BETWEEN 9120010 AND 9125514;
DELETE FROM `waypoint_data` WHERE (`id` > 91200100 OR (`id` = 91200100 AND `point` >= 1)) AND (`id` < 91203590 OR (`id` = 91203590 AND `point` <= 6));






